values ('storefront', '{"shipStandard":25,"shipExpress":45,"freeOver":300,"vat":15,"vatInclusive":true,"storeName":{"ar":"Health Harmony","en":"Health Harmony","tl":"Health Harmony"},"contacts":{"phone":"0550000000","email":"care@health-harmony.example","address":"الرياض — حي العليا (عدّل من لوحة الأدمن)","hours":"السبت–الخميس 9ص–9م"},"payments":{"cod":true,"bank":true,"bankName":"البنك الأهلي — Health Harmony (مثال)","bankIban":"SA00 0000 0000 0000 0000 0000","bankNote":"حوّل المبلغ على الآيبان ثم أرسل رقم الحوالة واتساب؛ يُشحن طلبك بعد تأكيد الحوالة."},"banners":[{"id":"b1","active":true,"sort":1,"title":{"ar":"عناية تبدأ من التفاصيل","en":"Care that starts with details","tl":"Care na nagsisimula sa detalye"},"sub":{"ar":"منتجات مختارة من موزعين معتمدين","en":"Curated from authorized distributors","tl":"Pinili mula sa awtorisadong distributor"},"ctaLink":"/shop"},{"id":"b2","active":true,"sort":2,"title":{"ar":"روتين رشاقة متوازن","en":"A balanced fitness routine","tl":"Balanseng fitness routine"},"sub":{"ar":"تجهيزات تدعم نشاطك اليومي في المنزل","en":"Gear for your home training days","tl":"Kagamitan para sa home workout mo"},"ctaLink":"/shop"}]}')
